/bin/bash -lc "cat > /workspace/inspect_targets.py <<'PY'
import sys, pysam
VCF_URL='https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/1000G_2504_high_coverage/working/20201028_3202_raw_GT_with_annot/20201028_CCDG_14151_B01_GRM_WGS_2020-08-05_chr1.recalibrated_variants.vcf.gz'
BASES=set('ACGT')

def parse_targets(path):
    targets=[]
    with open(path) as f:
        for line in f:
            if not line.strip(): continue
            c,start,end,rs=line.rstrip('\\n').split('\\t')
            targets.append((c,int(end),rs))
    return targets

def fmt_gt(gt):
    if gt is None: return './.'
    if isinstance(gt, tuple): gt='/'.join(str(x) if x is not None else '.' for x in gt)
    else: gt=str(gt)
    return gt

def norm_gt(gt):
    if isinstance(gt, tuple): alle=gt
    else:
        s=str(gt).replace('|','/')
        parts=s.split('/')
        alle=[]
        for p in parts:
            if p=='.': return './.'
            try: alle.append(int(p))
            except: return './.'
    # sort allele numbers for diploid; if non-diploid or missing -> ./.
    if len(alle)"'!=2 or any(a not in (0,1) for a in alle):
        return '"'./.'
    a,b=sorted(alle)
    return f'{a}/{b}'

targets=parse_targets(sys.argv[1])
vf=pysam.VariantFile(VCF_URL)
samples=list(vf.header.samples)
print(f'header_samples\\t{len(samples)}')
print(f'first_samples\\t{samples[:5]}')
print(f'last_samples\\t{samples[-5:]}')

counts={'valid':0,'missing':0,'multi_valid':0,'total_records':0,'total_valid_records':0,'phased_gt':0,'unphased_gt':0,'categories':{}}
rows=[]
for chrom,pos,rs in targets:
    recs=[]
    for rec in vf.fetch(chrom, pos-1, pos):
        if rec.pos==pos:
            recs.append(rec)
    counts['total_records']+=len(recs)
    valid=[]
    for rec in recs:
        if len(rec.alts)==1 and rec.ref in BASES and len(rec.ref)==1 and rec.alts[0] in BASES and len(rec.alts[0])==1:
            valid.append(rec)
    counts['total_valid_records']+=len(valid)
    if len(valid)==1:
        counts['valid']+=1
        rec=valid[0]
        # category counts and phased detection
        for s in samples:
            gt=rec.samples[s]['GT']
            if gt is not None:
                raw=fmt_gt(gt)
                if '|' in raw:
                    counts['phased_gt']+=1
                elif '/' in raw:
                    counts['unphased_gt']+=1
            n=norm_gt(gt)
            counts['categories'][n]=counts['categories'].get(n,0)+1
        rows.append((chrom,pos,rs,1,rec.ref,rec.alts[0]))
    elif len(valid)==0:
        counts['missing']+=1
        rows.append((chrom,pos,rs,0,'',''))
    else:
        counts['multi_valid']+=1
        rows.append((chrom,pos,rs,len(valid),';'.join(f'{r.ref}>{r.alts[0]}' for r in valid),''))

with open('inspection.tsv','w') as out:
    out.write('CHROM\\tPOS\\tRSID\\tVALID_COUNT\\tREF\\tALT\\n')
    for row in rows:
        out.write('\\t'.join(map(str,row))+'\\n')

with open('inspection_summary.txt','w') as out:
    for k,v in counts.items():
        out.write(f'{k}\\t{v}\\n')
PY"
